def find_path(o, key, path='$'):
    out = []
    if isinstance(o, dict):
        for k, v in o.items():
            if k == key:
                out.append((path + '.' + k, v))
            out.extend(find_path(v, key, path + '.' + k))
    elif isinstance(o, list):
        for n, v in enumerate(o):
            out.extend(find_path(v, key, '%s[%d]' % (path, n)))
    return out


